"""Design documents only: emit inert HTML/SVG, no application runtime or handlers.
Run from repository root: python docs/design/0028/selected-light-family/render-design.py
"""
from pathlib import Path
from html import escape
from html.parser import HTMLParser
import json, hashlib

ROOT = Path(__file__).resolve().parents[4]
OUT = Path(__file__).resolve().parent
SOURCE = '960d225c388912791443cbc68efe5e5426f2a9d2'

class Inventory(HTMLParser):
    def __init__(self, name):
        super().__init__(); self.name=name; self.items=[]; self.line=0
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag in ('input','select','textarea','button'):
            self.items.append(dict(file=self.name,line=self.getpos()[0],tag=tag,**a))

inventory=[]
for name in ['Index.html','MaintenancePages.html','KnowledgeSearchPage.html','GpWorkspacePage.html','EntityWorkspacePage.html','ActivityAnalyticsPage.html','RelationshipExplorerPage.html','AiProviderSettingsPage.html']:
    p=Inventory(name); p.feed((ROOT/'src'/name).read_text(encoding='utf-8')); inventory.extend(p.items)
(OUT/'source-controls.json').write_text(json.dumps({'source_sha':SOURCE,'controls':inventory},ensure_ascii=False,indent=2),encoding='utf-8')

